\begin{lemma}
\label{lemma:euler_method}
    Let $F:\mathbb{R}^n\rightrightarrows\mathbb{R}^n$ be an upper semicontinuous mapping with nonempty, compact, and convex values. Let $X_0$ be a compact subset of $\mathbb{R}^n$ and let $T>0$. Assume that there exist $\bar{\alpha},r>0$ such that for all $\alpha \in (0,\bar{\alpha}]$ and for all sequence $(x_k)_{k\in\mathbb{N}}$ such that
    \begin{equation}
    \label{eq:Euler}
                x_{k+1} \in x_k + \alpha F(x_k), ~~~ \forall k \in \mathbb{N},~~~ x_0 \in X_0,
    \end{equation}
    we have that $x_0,\hdots,x_{\lfloor T/\alpha \rfloor+1} \in B(0,r)$. For all $\epsilon>0$, there exists $\hat{\alpha}\in (0,\bar{\alpha}]$ such that for all $\alpha \in (0,\hat{\alpha}]$ and for all sequence $(x_k)_{k\in\mathbb{N}}$ satisfying \eqref{eq:Euler}, there exists an absolutely continuous function $x:[0,T]\rightarrow\mathbb{R}^n$ such that
    \begin{equation}
    \label{eq:ivp}
                x'(t) \in F(x(t)),~~~ \text{for a.e.}~ 
                t \in (0,T), ~~~ x(0) \in X_0, 
    \end{equation}
    for which $\|\bar{x}(t) - x(t) \| \leqslant \epsilon$ for all $t \in [0,T]$, where $\bar{x}:[0,T]\rightarrow\mathbb{R}^n$ is defined by $\bar{x}(t) := x_k + (t-\alpha k)/\alpha  (x_{k+1}-x_k)$ for all $t\in [\alpha k , \min\{\alpha(k+1),T\}]$ and $k\in \{0,\hdots,\lfloor T/\alpha\rfloor\}$.
\end{lemma}

\begin{proof}
Let $(\alpha_m)_{m \in \mathbb{N}}$ denote a sequence of positive numbers that converges to zero. Without loss of generality, we may assume that the sequence is bounded above by $\bar{\alpha}$. To each term in the sequence, we attribute a sequence $(x_k^{m})_{k\in\mathbb{N}}$ generated by the Euler method with step size $\alpha_m$ and initialized in $X_0$, that is to say, which satisfies \eqref{eq:Euler} with $\alpha:=\alpha_m$. By assumption, $x_0^{m},\hdots,x_{\lfloor T/\alpha_m \rfloor+1}^{m} \in B(0,r)$. Consider the linear interpolation of those iterates, that is to say, the function $\bar{x}^{m}:[0,T]\rightarrow\mathbb{R}^n$ defined by $\bar{x}^{m}(t) := x_k^{m} + (t-\alpha_m k)(x_{k+1}^{m}-x_k^{m})/\alpha_m$ for all $t\in [\alpha_m k , \min\{\alpha_m(k+1),T\}]$ and $k\in \{0,\hdots,\lfloor T/\alpha_m \rfloor\}$. Since $B(0,r)$ is convex, it holds that $\|\bar{x}^{m}(t)\| \leqslant r $ for all $t\in [0,T]$. In addition, since $F$ is upper semicontinuous and compact valued, by \cite[Proposition 3 p. 42]{aubin1984differential} there exists $r'>0$ such that $F(B(0,r)) \subset B(0,r')$. Observe that $(\bar{x}^{m})'(t) = (x_{k+1}^{m}-x_k^{m})/\alpha_m \in F(x_k^{m})$ for all $t\in (\alpha_m k , \min\{\alpha_m(k+1),T\})$ and $k\in \{0,\hdots,\lfloor T/\alpha_m \rfloor\}$. Hence, we have that $\|(\bar{x}^{m})'(t)\| \leqslant r'$ for almost every $t\in (0,T)$. By successively applying the Arzel\`a-Ascoli and the Banach-Alaoglu theorems (see \cite[Theorem 4 p. 13]{aubin1984differential}), there exists a subsequence (again denoted $(\alpha_{m})_{m\in \mathbb{N}}$) and an absolutely continuous function $x:[0,T]\rightarrow \mathbb{R}^n$ such that $\bar{x}^{m}(\cdot)$ converges uniformly to $x(\cdot)$ and $(\bar{x}^{m})'(\cdot)$ converges weakly to $x'(\cdot)$ in $L^1([0,T],\mathbb{R}^n)$. Furthermore, for all $t\in (\alpha_{m} k , \min\{\alpha_{m}(k+1),T\})$ and $k \in \{0,\hdots,\lfloor T/\alpha_m \rfloor\}$, observe that
\begin{subequations}
\begin{align*}
    (\bar{x}^{m}(t),(\bar{x}^{m})'(t)) 
    & = \left(x_k^{m} + (t-\alpha_m k)\frac{x_{k+1}^{m}-x_k^{m}}{\alpha_m},\frac{x_{k+1}^{m}-x_k^{m}}{\alpha_m}\right) \\
    & \in \left(\{x_k^{m}\} + (t-\alpha_m k)F(x_k^{m})\right) \times F(x_k^{m})  \\
    & = \{x_k^{m}\} \times F(x_k^{m}) + (t-\alpha_m k)F(x_k^{m}) \times \{0\}  \\
    & \subset \mathrm{graph}(F) + B(0,r'\alpha_m)\times \{0\}.
\end{align*}
\end{subequations}
According to \cite[Convergence Theorem p. 60]{aubin1984differential}, it follows that $x'(t) \in F(x(t))$ for almost every $t\in (0,T)$. The sequence of initial points $(x^{m}(0))_{m\in\mathbb{N}}$ lies in the closed set $X_0$, hence its limit $x(0)$ lies in $X_0$ as well. As a result, $x(\cdot)$ is a solution to the differential inclusion \eqref{eq:ivp}. 

To sum up, we have shown that for every sequence $(\alpha_m)_{m \in \mathbb{N}}$ of positive numbers converging to zero, there exists a subsequence for which the corresponding linear interpolations uniformly converge towards a solution of the differential inclusion \eqref{eq:ivp}. The conclusion of the theorem now easily follows. To see why, one can reason by contradiction and assume that there exists $\epsilon>0$ such that for all $\hat{\alpha} \in (0,\bar{\alpha}]$, there exist $\alpha \in (0,\hat{\alpha}]$ and a sequence $(x_k)_{k \in \mathbb{N}}$ generated by the Euler method with step size $\alpha$ and initialized in $X_0$ such that, for any solution $x(\cdot)$ to the differential inclusion \eqref{eq:ivp}, it holds that $\|\bar{x}(t) - x(t) \| > \epsilon$ for some $t \in [0,T]$. We can then generate a sequence $(\alpha_m)_{m \in \mathbb{N}}$ of positive numbers converging to zero such that, for any solution $x(\cdot)$ to the differential inclusion \eqref{eq:ivp}, it holds that $\|\bar{x}^{m}(t) - x(t) \| > \epsilon$ for some $t \in [0,T]$. Since there exists a subsequence $(\alpha_{\varphi(m)})_{m \in \mathbb{N}}$ such that $\bar{x}^{\varphi(m)}$ uniformly converges to a solution to the differential inclusion \eqref{eq:ivp}, we obtain a contradiction. 
\end{proof}

\begin{proof}
Let $x^* \in \mathbb{R}^n$ denote a stable point of a locally Lipschitz semi-algebraic function $f:\mathbb{R}^n\rightarrow\mathbb{R}$. We reason by contradiction and assume that $x^*$ is not a local minimum of $f$. Given $x\in \mathbb{R}^n$ and $S \subset \mathbb{R}^n$, let $d(x,S) := \inf \{\|x - y\| : y \in S\}$. According to the Kurdyka-\L{}ojasiewicz inequality \cite[Theorem 14]{bolte2007clarke} (see also \cite[Theorem 4.1]{attouch2010proximal}), there exist $r,\rho>0$ and a strictly increasing concave continuous semi-algebraic function $\psi:[0,\rho) \rightarrow [0,\infty)$ that is continuously differentiable on $(0,\rho)$ with $\psi(0) = 0$ such that $d(0,\partial f(x)) \geqslant 1/\psi'(|f(x) - f(x^*)|)$ for all $x \in B(x^*,r)$ whenever $0<|f(x)-f(x^*)|< \rho$. After possibly reducing $r$, the inequality holds for all $x \in B(x^*,r)$ such that $f(x) \neq f(x^*)$. 

Let $\epsilon \in (0,r/2)$. By the definition of stability (Definition \ref{def:discrete_lyapunov}), there exist $\delta>0$ and $\bar{\alpha}>0$ such that for all $\alpha \in (0,\bar{\alpha}]$, the subgradient method with constant step size $\alpha$ initialized in $B(x^*,\delta)$ has all its iterates in $B(x^*,\epsilon)$. Since $x^*$ is not a local minimum, we can take an initial iterate $x_0$ in $B(x^*,\delta)$ such that $f(x_0)<f(x^*)$. Let $L>0$ denote a Lipschitz constant of $f$ on $B(x^*,r)$ and let $T := (2\epsilon + \delta)L\psi'(f(x^*) - f(x_0))^2>0$.
Consider the differential inclusion
\begin{equation}
\label{eq:ivp_x_0}
     x'(t) \in - \partial f(x(t)), ~~~ \text{for a.e.}~ 
     t \in (0,T),~~~ x(0) = x_0.
\end{equation}
Since $f$ is locally Lipschitz, the set-valued function $-\partial f$ is upper semicontinuous \cite[2.1.5 Proposition (d)]{clarke1990} with nonempty, compact and convex values \cite[2.1.2 Proposition (a)]{clarke1990}. By Lemma \ref{lemma:euler_method}, there exists $\hat{\alpha} \in (0,\bar{\alpha}]$ such that, for all $\alpha \in (0,\hat{\alpha}]$  and for all sequence $(x_k)_{k\in \mathbb{N}}$ generated by the subgradient method with constant step size $\alpha$ and initialized at $x_0$, there exists a solution $x(\cdot)$ to the differential inclusion \eqref{eq:ivp_x_0} for which $\|\bar{x}(t) - x(t)\| \leqslant \epsilon/2$ for all $t \in [0,T]$, where $\bar{x}:[0,T]\rightarrow\mathbb{R}^n$ is the piecewise linear function defined by $\bar{x}(t) := x_k + (t-\alpha k)/\alpha  (x_{k+1}-x_k)$ for all $t\in [\alpha k , \min\{\alpha(k+1),T\}]$ and $k\in \{0,\hdots,\lfloor T/\alpha\rfloor\}$.

Let us fix some $\alpha \in (0,\min\{\hat{\alpha},T/10\}]$ from now on. Consider a sequence $(x_k)_{k\in\mathbb{N}}$ generated by the subgradient method with constant step size $\alpha$ and initialized at $x_0$. Consider also the linear interpolation $\bar{x}(\cdot)$ of those iterates up to iteration $K+1$ where $K := \lfloor T/\alpha \rfloor$, as well as a solution $x(\cdot)$ to the differential inclusion \eqref{eq:ivp_x_0} such that $\|\bar{x}(t)-x(t)\| \leqslant \epsilon/2$ for all $t\in [0,T]$. Since $f$ is semi-algebraic, by \cite[Lemma 5.2]{davis2020stochastic} (see also \cite{drusvyatskiy2015curves}) it holds that
\begin{equation}
\label{eq:lyapunov}
    f(x(t)) - f(x(0)) = - \int_0^t d(0,\partial f(x(\tau)))^2 d\tau, ~~~ \forall t \in [0,T].
\end{equation}
As a result, $f(x(t)) \leqslant f(x(0)) = f(x_0)$ for all $t \in [0,T]$. Also, $\|x(t) - x^*\| \leqslant \|x(t) - \bar{x}(t)\| + \|\bar{x}(t) - x^*\| \leqslant \epsilon/2 + \epsilon = 3\epsilon/2 \leqslant r$, where the inequality $\|\bar{x}(t) - x^*\| \leqslant \epsilon$ follows from the convexity of $B(x^*,\epsilon)$. Hence $0<f(x^*) - f(x_0) \leqslant f(x^*) - f(x(t))$ and $d(0,\partial f(x(t))) \geqslant  1/\psi'(f(x^*)-f(x(t))) \geqslant 1/\psi'(f(x^*)-f(x_0))$ for all $t\in[0,T]$ by concavity of $\psi$. Together with \eqref{eq:lyapunov}, it follows that $f(x(K\alpha)) - f(x_0) \leqslant -K\alpha M^2$ where $K := \lfloor T/\alpha \rfloor$ and $M:= 1/\psi'(f(x^*)-f(x_0))$. Recall that $L$ is a Lipschitz constant of $f$ on $B(x^*,r)$, so that we have $|f(x(K\alpha))-f(x_0)| \leqslant L \|x(K\alpha)-x_0\|$. We thus obtain the lower bound $\|x(K\alpha)-x_0\| \geqslant K\alpha M^2/L = \lfloor T/\alpha \rfloor \alpha M^2/L \geqslant (T-\alpha)M^2/L \geqslant (T-T/10)M^2/L = 9/10( 2\epsilon + \delta) $ (recall that $T = (2\epsilon + \delta)L/M^2$). Hence $\|x(K\alpha)-x^*\| \geqslant \|x(K\alpha)-x_0\| - \|x_0-x^*\| \geqslant 9/10(2\epsilon + \delta) - \delta = 9 \epsilon/5 - \delta/10 \geqslant 9 \epsilon/5 - \epsilon/10 = 17\epsilon/10$ and finally $\|x_K-x^*\| \geqslant \|x(K\alpha)-x^*\| -\|x_K-x(K\alpha)\| \geqslant 17\epsilon/10 - \epsilon/2 = 6\epsilon/5>\epsilon$. However, since $0<\alpha \leqslant \hat{\alpha} \leqslant \bar{\alpha}$ and $x_0 \in B(x^*,\delta)$, by stability of $x^*$ we have $x_K \in B(x^*,\epsilon)$. We have reached a contradiction. 
\end{proof}

